        }



        if (!GetIconInfo(icon, &info)) {

            CURSOR_ERROR("Could not get icon info");

            goto icon_error;

        }



        pos.x = ci.ptScreenPos.x - clip_rect.left - info.xHotspot;

        pos.y = ci.ptScreenPos.y - clip_rect.top - info.yHotspot;



        if (hwnd) {

            RECT rect;



            if (GetWindowRect(hwnd, &rect)) {

                pos.x -= rect.left;

